(function (all) { var mine = all["it"] = all["it"] || {}; var add = {"manual.831d0f72d242":"Per iniziare","manual.f2f53974b760":"Freally Capture è uno studio desktop per Windows, macOS e Linux. Questo manuale descrive la versione 1.2.1, quella attuale.","manual.4b5f10daa08b":"Apri Freally Capture. La prima volta ti chiede di accettare il contratto di licenza; poi una procedura guidata di configurazione esamina la scheda grafica e il processore e propone un encoder, una dimensione della tela e un bitrate, spiegando il motivo di ciascuna scelta.","manual.fe88634050bf":"Lo studio si apre sull'anteprima del programma con i pannelli <strong>Scene</strong>, <strong>Sorgenti</strong>, <strong>Mixer</strong> e <strong>Controlli</strong>. Non ci sono account né accessi.","manual.4c937d2528ca":"Su <strong>macOS</strong>, consenti <strong>Registrazione schermo</strong> (e <strong>Fotocamera</strong> e <strong>Microfono</strong>, se li usi) in Impostazioni di Sistema → Privacy e sicurezza, poi riapri l'app. Su <strong>Linux con Wayland</strong>, è la finestra di dialogo del desktop a chiederti quale schermo o finestra condividere.","manual.adc8f305f8f8":"Aggiungi la tua prima sorgente (vedi <a href=\"#build-a-scene\">Crea una scena</a>) e sei pronto per registrare o andare in diretta.","manual.46e49bd74b1d":"Crea una scena","manual.f779d891c1f2":"Una scena è una pila di sorgenti composte sulla scheda grafica. Una sorgente può essere condivisa da più scene.","manual.5a1c5f778fdb":"Nel pannello <strong>Sorgenti</strong>, fai clic su <strong>Aggiungi sorgente</strong> e scegli un tipo: <strong>Schermo</strong>, <strong>Finestra</strong>, <strong>Gioco</strong>, <strong>Webcam / scheda di acquisizione</strong>, <strong>Browser</strong>, <strong>Media</strong>, <strong>Immagine</strong>, <strong>Testo</strong>, <strong>Colore</strong> o <strong>Audio</strong>.","manual.2a2d9e2015b5":"Aggiungi una <strong>Cattura schermo</strong>: l'anteprima del programma si riempie con il tuo schermo.","manual.80c8e9c8176f":"Aggiungi una sorgente <strong>Webcam</strong>, trascinala in un angolo della tela e ridimensionala con le sue maniglie.","manual.264150f36676":"Aggiungi sopra una sovrimpressione <strong>Immagine</strong> o <strong>Browser</strong>. L'ordine dell'elenco è l'ordine sulla tela: la cima dell'elenco è in primo piano.","manual.a329c46899d6":"Crea altre scene nel pannello <strong>Scene</strong> (ad esempio «A breve in diretta», «Gameplay» e «Torno subito») e passa dall'una all'altra.","manual.9c8d5730d1bb":"<strong>Suggerimento:</strong> modifica una volta le proprietà di una sorgente condivisa e cambiano in ogni scena che la usa.","manual.fd869e76d280":"<strong>L'anteprima:</strong> su Windows, macOS e Linux con X11, l'anteprima del programma viene disegnata direttamente dalla scheda grafica, così trascinamento, scala e rotazione sono immediati. Su Wayland si usa un'anteprima standard, con la stessa modifica sulla tela.","manual.87eca68fecaa":"Filtri e transizioni","manual.36a962cf3902":"Impila i filtri su ogni sorgente, sulla scheda grafica, e scegli come una scena lascia il posto alla successiva.","manual.4708b4dbab34":"Aggiungere un chroma key","manual.9df34cebcaf5":"Fai clic destro su una sorgente (ad esempio una videocamera davanti a un green screen) e scegli <strong>Filtri</strong>.","manual.9981601a6174":"Aggiungi <strong>Chroma Key</strong> e regola <strong>Colore chiave</strong>, <strong>Similarità</strong>, <strong>Morbidezza</strong> e <strong>Spill</strong>: il colore scontornato scompare dal vivo sulla tela.","manual.b76bd309a9f6":"Aggiungi altri filtri quando ti servono (<strong>Correzione colore</strong>, <strong>LUT</strong>, <strong>Sfocatura</strong>, <strong>Maschera</strong>, <strong>Nitidezza</strong>) e trascinali per riordinare la catena.","manual.db41fe5a40e4":"Impostare una transizione","manual.bea9e11be98d":"In <strong>Controlli</strong>, apri il selettore delle transizioni, scegli <strong>Taglio</strong>, <strong>Dissolvenza</strong>, <strong>Scorrimento</strong>, <strong>Swipe</strong>, <strong>Stinger</strong> o <strong>Luma Wipe</strong> e imposta una durata.","manual.eada58ce5b2e":"Per uno <strong>Stinger</strong>, scegli il file multimediale e il suo punto di transizione; per un <strong>Luma Wipe</strong>, scegli il gradiente e la sua morbidezza.","manual.79756cb8b209":"Cambia scena per vedere la transizione. In modalità Studio parte quando mandi l'anteprima in programma.","manual.2c0c025b4264":"Compositore ed effetti visivi","manual.b768e85eff32":"Inclinazione 3D, keyer di uscita, fermo immagine e clonazione, una famiglia di sfocature, transizioni di movimento con regole, uno studio di shader, maschere Bézier e stinger con track matte.","manual.d2b720eca5a5":"Inclinazione 3D e prospettiva","manual.d665cc2f2296":"Apri <strong>Modifica trasformazione</strong> su un elemento e imposta <strong>Inclinazione X</strong>, <strong>Inclinazione Y</strong> e un'intensità di <strong>Prospettiva</strong> per collocare la sorgente in 3D. Una trasformazione senza inclinazione viene resa esattamente come prima.","manual.c4077ba2b72d":"Keyer di uscita","manual.d4220af54ed9":"Apri <strong>Strumenti → Keyer di uscita</strong> e aggiungi qualsiasi sorgente come livello sopra l'<strong>uscita programma</strong>, al di sopra di ogni scena e attraverso ogni cambio di scena: un logo dell'emittente, un badge LIVE, un sottopancia.","manual.0677e571c1f8":"Riordina i livelli e imposta per ciascuno opacità, posizione, dimensione e attivazione. Compaiono allo stesso modo nell'anteprima, nella registrazione, nella diretta e nella multiview.","manual.1e484119e149":"Fermo immagine e clonazione delle sorgenti","manual.4cdb8e22f58b":"Fai clic destro su una sorgente, apri <strong>Filtri</strong> e aggiungi <strong>Congela</strong>: trattiene l'ultimo fotogramma nel programma, nell'anteprima, nella registrazione e nella diretta insieme. Disattivalo per sbloccare l'immagine.","manual.59fd957b48dc":"Fai clic sul pulsante <strong>Clona</strong> (⧉) nella riga di una sorgente per mettere uno stesso segnale in più scene o posizioni, ogni clone con la propria trasformazione e i propri filtri.","manual.a90410d6b30c":"Sfocature","manual.eeb69e428aa3":"Nei <strong>Filtri</strong> di una sorgente, aggiungi una delle sfocature accanto a quella gaussiana: <strong>direzionale</strong> (una scia di movimento inclinata), <strong>radiale</strong> (una rotazione attorno a un centro), <strong>Zoom</strong> (una scia in stile dolly zoom) o <strong>Pixel</strong> (un mosaico).","manual.54261c9f6b8f":"La transizione di movimento e le regole di transizione","manual.ef17a04962be":"Scegli la transizione <strong>Movimento</strong>: gli elementi presenti in entrambe le scene scivolano dalla vecchia posizione, scala, rotazione e ritaglio a quelli nuovi invece di tagliare, e gli elementi presenti in una sola scena appaiono o scompaiono in dissolvenza.","manual.e31792f9e737":"Apri <strong>Strumenti → Regole di transizione</strong> per assegnare a una coppia di scene una transizione e una durata proprie. Per l'entrata di un singolo elemento, imposta una dissolvenza in entrata <strong>Rivelazione</strong> in <strong>Modifica trasformazione</strong>.","manual.bb4e30a1ea68":"Lo studio di shader WGSL","manual.e475acf03bea":"Aggiungi un <strong>effetto WGSL dell'utente</strong> come filtro e modificalo dal vivo. I suoi cursori nascono dalle annotazioni <code>// @param</code>, e una galleria integrata offre scala di grigi, inversione, linee di scansione e vignettatura.","manual.424ca3316822":"<strong>Suggerimento:</strong> uno shader viene compilato e verificato mentre scrivi. Uno shader non valido viene ignorato e la sorgente viene resa senza filtro: mai un crash.","manual.c24e8b5ee2c0":"Maschere Bézier","manual.37870edaacbc":"Aggiungi il filtro <strong>maschera a mano libera</strong> e disegna un tracciato chiuso: trascina le maniglie, fai doppio clic per aggiungere un punto, clic destro per rimuoverlo. Offre forme predefinite, una sfumatura per ogni bordo e l'inversione.","manual.f44ad1306530":"Esporta qualsiasi tracciato come motivo <strong>luma-wipe</strong> in scala di grigi per riutilizzare la forma come transizione.","manual.e4c8b0c52b3e":"Stinger con track matte","manual.b35494db6ce6":"Imposta uno stinger perché porti la propria trasparenza come <strong>traccia matte</strong>, con riempimento e matte <strong>affiancati</strong> o <strong>impilati</strong>, così la trasparenza sopravvive ai codec che la scartano (H.264 e HEVC). Facoltativamente <strong>abbassa l'audio del programma</strong> sotto il suono proprio dello stinger mentre suona.","manual.3879f0c73d18":"Sovrimpressioni e altre sorgenti","manual.cea21c089e39":"Replay, playlist, titoli, misuratori, una sovrimpressione delle statistiche, timer, una sovrimpressione degli input e due segnali di rete, tutti dal menu <strong>+ / Aggiungi sorgente</strong> del pannello <strong>Sorgenti</strong>.","manual.4a459b922e4b":"Replay istantaneo","manual.2e042aa67065":"Prima arma il buffer di replay (<strong>Arma il replay</strong> nel pannello <strong>Controlli</strong>), poi scegli <strong>Replay istantaneo</strong> da <strong>+ / Aggiungi sorgente</strong> e collocalo in una scena.","manual.d7645da473a6":"Manda in programma gli ultimi secondi con la tua scorciatoia del replay: vengono copiati senza ricodifica e riprodotti a velocità <strong>100%</strong>, <strong>50%</strong> o <strong>25%</strong>, rallentati anziché riempiti di fotogrammi inventati. Puoi scorrere o mettere in pausa durante la riproduzione.","manual.5b8095e70de0":"Alla fine la sorgente si svuota da sola, così lo show torna in diretta da solo.","manual.6433eaab9b10":"<strong>Suggerimento:</strong> il replay al rallentatore è muto di proposito: l'audio rallentato risulterebbe impastato, quindi viene omesso invece di essere simulato.","manual.f0b63d46cd74":"Playlist multimediale e musica di sottofondo","manual.37ed12f9d130":"Aggiungi <strong>Playlist multimediale (senza stacchi)</strong> e crea un elenco ordinato con punti di ingresso e di uscita e punti di cue per ogni elemento. L'intero elenco passa per un unico decoder, così i raccordi sono precisi al fotogramma e davvero senza stacchi.","manual.ef41fa6ad9b5":"Scegli come procede (<strong>Loop</strong>, <strong>Casuale</strong> o <strong>tieni l'ultimo</strong>) e scorrila con le scorciatoie per l'elemento successivo e precedente. Una playlist di solo audio mostra il <strong>nome della traccia corrente</strong> sulla tela e suona attraverso il proprio canale del mixer; fai clic sul pulsante <strong>Monitor</strong> di quel canale per ascoltarla.","manual.6e641ae2bd92":"Per una musica che suona senza nulla sullo schermo, scegli invece <strong>+ / Aggiungi sorgente → Musica di sottofondo…</strong> e seleziona uno o più file <code>.mp3</code>, <code>.wav</code> o <code>.flac</code>, in ordine casuale se vuoi. Silenzia il suono proprio di uno sfondo video, così si sente sempre una cosa sola.","manual.b9aad55133bf":"Il designer di titoli e tabelloni","manual.5382c093aaef":"Aggiungi <strong>Titolo / Tabellone</strong> per aprire il designer: impila livelli di <strong>testo</strong>, <strong>immagine</strong> e <strong>forma</strong>, con testo con contorno e ombra e animazioni di entrata e uscita (dissolvenza, scorrimento, tendina).","manual.7b8fea70655a":"Collega i campi a un file monitorato (una cella CSV o un puntatore JSON) o a una variabile dello studio, poi controllalo dal vivo: cambia un nome, modifica il punteggio o avvia l'animazione senza toccare la scena.","manual.88a9422e37a9":"Il visualizzatore audio","manual.87f4a5bdd624":"Aggiungi <strong>Visualizzatore audio</strong> e scegli uno stile (<strong>Barre di spettro</strong>, un <strong>Oscilloscopio</strong> o dei <strong>VU meter</strong> stereo), poi collegalo a qualsiasi canale del mixer, traccia o al mix master. Mostra anche il suono di uno sfondo video.","manual.0ae90a461adb":"Nelle <strong>Proprietà</strong> della sorgente, attiva <strong>Colori classici</strong> per le fasce verde, gialla e rossa, oppure lascialo disattivato per un unico colore pieno. Lì trovi anche dimensione, numero di barre e velocità di caduta.","manual.0d1ceffb08ba":"<strong>Suggerimento:</strong> il visualizzatore ascolta <strong>dopo il fader</strong>, quindi una sorgente silenziata appare piatta: mostra esattamente ciò che senti.","manual.ec642e1cf0cc":"La sovrimpressione delle statistiche, il timer a split e la sovrimpressione degli input","manual.6b4fe6f81cb0":"Aggiungi <strong>Statistiche di prestazione (HUD)</strong> per mostrare sulla tela i valori misurati dal pannello delle statistiche (fotogrammi al secondo, CPU, memoria, tempo di composizione GPU, fotogrammi persi e bitrate dal vivo), ogni riga attivabile o disattivabile. L'utilizzo della GPU è omesso di proposito, perché non viene misurato.","manual.cbd8a4b88736":"Aggiungi <strong>Timer split (speedrun)</strong>, importa un file LiveSplit <code>.lss</code> ed eseguilo con le scorciatoie globali per split, annulla, salta e azzera, confrontandoti con il record personale, i migliori segmenti o la media. Il file viene solo letto; una run non viene mai riscritta su di esso.","manual.fbf4bbeaf903":"Aggiungi <strong>Sovrimpressione input (tasti/pad)</strong> per mostrare dal vivo tastiera, mouse e gamepad, in uno di quattro layout (WASD, una tastiera compatta, un pad a doppio stick, un fight stick a 8 direzioni). Tastiera e mouse funzionano su Windows; i gamepad funzionano su tutti e tre i sistemi.","manual.bf794edb3c25":"La barra dei social e dei canali","manual.5f898056ef11":"Aggiungi <strong>Barra social</strong> da <strong>+ / Aggiungi sorgente</strong>: un pannello che elenca i tuoi nomi utente. Scegli una piattaforma per ogni riga (<strong>YouTube, Twitch, Kick, X, Instagram, TikTok, Facebook, Discord</strong> come badge colorati, oppure <strong>Personalizzato</strong> con etichetta e colore tuoi) e digita il nome utente (ad esempio <code>@mychannel</code>). Aggiungi una riga di intestazione facoltativa («Seguimi»), riordina le righe e imposta dimensione e colori del testo.","manual.1dab9389547a":"Ogni campo resta modificabile nelle <strong>Proprietà</strong> della sorgente. Le righe senza nome utente vengono saltate, così puoi tenere un elenco completo e compilare solo ciò che usi.","manual.1a4ac3c2e0bf":"Il messaggio di chat in evidenza","manual.c5d58a7d58be":"Apri <strong>Strumenti → Messaggio chat in evidenza…</strong> (o la palette dei comandi). Elenca le righe più recenti di ogni sovrimpressione della chat attiva: fai clic su <strong>Metti in evidenza</strong> su una di esse per fissarla nel programma come banner, visibile a chi guarda la diretta e la registrazione.","manual.162d364796a2":"Imposta i colori del <strong>banner</strong> e del <strong>testo</strong> nella finestra di dialogo, e fai clic su <strong>Rimuovi</strong> per toglierlo dall'onda. Il messaggio fissato si cancella al riavvio, per scelta: il saluto di ieri non torna mai a perseguitare lo show di oggi.","manual.89a84c53e014":"Evidenziazione del cursore ed effetti dei clic","manual.d0a5d9fb047d":"Fai clic destro su una cattura di schermo o di finestra, apri <strong>Filtri</strong> e aggiungi <strong>Effetti del cursore</strong>: un <strong>Alone del cursore</strong> (colore e raggio), <strong>Onde di clic</strong> con colori diversi per il tasto sinistro e destro e, facoltativamente, <strong>Tasti in sovrimpressione</strong> accanto al puntatore. Le modifiche si vedono dal vivo.","manual.4a17c44757e4":"<strong>Nota:</strong> gli effetti del cursore funzionano solo su Windows; macOS e Linux disegnano il cursore da sé. La sovrimpressione degli input e i tasti in sovrimpressione leggono l'input <strong>solo mentre sono attivi</strong> e lo disegnano direttamente nell'immagine: nulla viene memorizzato o registrato.","manual.8bdb1aadf964":"Sorgenti di rete: ricezione LAN e Freally Link","manual.797fe86a1fe8":"Aggiungi <strong>Ricezione LAN (listener SRT/RTMP)</strong> per aprire un listener su questo computer, poi punta un'app di videocamera per telefono, un encoder o un secondo computer all'indirizzo mostrato (con un codice QR). Il segnale arriva nella scena con il proprio canale nel mixer. SRT può portare una passphrase AES facoltativa; RTMP non ha un'autenticazione propria, quindi il modulo preferisce SRT.","manual.e2761818ccef":"Per condividere tra due copie di Freally Capture, attiva l'uscita <strong>Freally Link</strong> sul computer che <strong>invia</strong> e imposta la sua <strong>chiave di associazione</strong>: senza di essa non si può attivare. Sul computer che <strong>riceve</strong>, aggiungi <strong>Freally Link (altra istanza)</strong>, fai clic su <strong>Scansiona la LAN</strong> e digita la chiave: il programma del mittente appare come sorgente. Nessuno dei due lati ha bisogno di ffmpeg, e un ricevitore senza la chiave non vede mai un fotogramma.","manual.a793cb271e32":"<strong>Nota:</strong> entrambe le sorgenti di rete sono <strong>disattivate finché non le aggiungi</strong>, restano sulla tua rete e non toccano mai internet: nessuno ti trova e niente chiama all'esterno.","manual.de10be5dcf2c":"Il conto alla rovescia «A breve in diretta»","manual.71b47ef78ea4":"Una schermata d'attesa prima dello show in un clic: un grande conto alla rovescia fino all'inizio sopra un'immagine, una GIF, un video, un gradiente o della musica, che lampeggia allo zero e aspetta che tu passi allo show.","manual.303493002776":"Aggiungere il conto alla rovescia","manual.f78f2994b5d5":"Nel pannello <strong>Sorgenti</strong>, apri <strong>+ / Aggiungi sorgente</strong> e scegli <strong>A breve in diretta…</strong>. Colloca nella scena un conto alla rovescia a tutta tela: una didascalia sopra un grande numero.","manual.c4bff5a4f06e":"Digita la <strong>didascalia</strong> («A breve in diretta», «Torno subito»), poi imposta l'orario con il <strong>selettore dell'orario</strong>: un'<strong>ora</strong> (1–12), un <strong>minuto</strong> a passi di cinque minuti e <strong>AM</strong> o <strong>PM</strong>. La sorgente conta alla rovescia fino a quell'ora del giorno.","manual.59b00df516f1":"Allo zero il conto alla rovescia <strong>lampeggia e resta fermo su 0:00:00</strong>: non cambia mai scena da solo. Passa alla tua scena dal vivo quando sei pronto. Ogni campo resta modificabile nelle <strong>Proprietà</strong> della sorgente.","manual.1dfb2d817d39":"Scegliere uno sfondo","manual.edc2450aeecd":"Scegli il riempimento: un <strong>Gradiente</strong> a due colori (predefinito), un colore <strong>Tinta unita</strong>, un'<strong>Immagine</strong> (fai clic su <strong>Sfoglia…</strong>) oppure <strong>Trasparente</strong> per lasciar vedere una sorgente sottostante.","manual.07a5fd9ac032":"Scegli un file <strong>GIF</strong> o <strong>video</strong> e va in loop dietro i numeri, <strong>ridimensionato per adattarsi e centrato</strong>, così si vede l'intera immagine e nulla viene ritagliato.","manual.1cda5be75376":"Aggiungi la <strong>Musica di sottofondo</strong> con <strong>Sfoglia…</strong> nella finestra di dialogo (MP3, WAV, FLAC, M4A, AAC, OGG o Opus). Va in loop, la senti nell'anteprima e fa parte della registrazione e della diretta. Il suono proprio di uno sfondo video viene silenziato, così si sente sempre una cosa sola.","manual.b39b6b7add20":"<strong>Suggerimento:</strong> per una musica dietro una schermata semplice, lascia lo sfondo su Gradiente o Trasparente e aggiungi la musica: un conto alla rovescia pulito con una colonna sonora.","manual.84f506f4fca5":"Il mixer audio","manual.480e299c8728":"Mixa ogni sorgente audio, inviala a un massimo di 6 tracce e ripulisci il tuo microfono, tutto dal vivo.","manual.bcbc220b3e63":"Ogni sorgente audio è un canale nel <strong>Mixer</strong>: il nome, un misuratore di livello, un fader, muto, monitor, filtri e pallini delle tracce (1–6).","manual.03b920dc5376":"Trascina un fader per impostare il livello, fai clic su <strong>Muto</strong> o <strong>Monitor</strong> e invia la sorgente a una qualsiasi delle 6 tracce.","manual.9a9991c7dc36":"Apri i <strong>filtri</strong> di una sorgente e aggiungi <strong>Denoise</strong> (elaborazione del segnale classica, senza IA), <strong>Noise Gate</strong>, <strong>Compressore</strong>, <strong>Limiter</strong>, <strong>EQ</strong> o <strong>Guadagno</strong>.","manual.1a58b91bc5aa":"Assegna una scorciatoia <strong>Push-to-talk</strong> o <strong>Push-to-mute</strong> e tieni d'occhio il misuratore <strong>LUFS</strong> per il volume percepito del programma.","manual.7158a36ed4d5":"<strong>Nota per macOS:</strong> macOS non fornisce da solo alle app «ciò che senti». Usa l'audio di ScreenCaptureKit (macOS 13 o successivo) dove è disponibile, oppure installa un dispositivo virtuale come BlackHole e sceglilo come sorgente dell'audio di sistema. Freally Capture ti guida e continua a registrare anche se una sorgente non si apre.","manual.bfdd510698ef":"Registrare","manual.e39b756fce99":"Registra il programma su più tracce con l'encoder hardware della scheda grafica, oppure senza perdite nel formato proprio di Capture.","manual.ad438c2dbf4b":"In <strong>Impostazioni → Uscita</strong>, scegli un encoder. Freally Capture trova <strong>NVENC</strong>, <strong>Quick Sync</strong>, <strong>AMF</strong>, <strong>VAAPI</strong> o <strong>VideoToolbox</strong> e sceglie il migliore; <strong>x264</strong> sul processore è sempre disponibile come ripiego.","manual.3bc1870f8449":"Scegli un contenitore (<strong>MP4</strong>, <strong>MKV</strong>, <strong>MOV</strong> o <strong>WebM</strong>) oppure il formato senza perdite proprio di Capture, <strong>freally-video</strong> (<code>.frec</code>), che non richiede altro da installare.","manual.e2a332927058":"Invia le sorgenti alle tracce audio (fino a 6) così microfono, audio di sistema e ospiti restano separati per il montaggio. Facoltativamente attiva la <strong>suddivisione dei file</strong> e <strong>una copia locale a tracce separate durante la diretta</strong>.","manual.e0fa2f5a9430":"Fai clic su <strong>Avvia registrazione</strong> in <strong>Controlli</strong>. Un pallino verde <strong>REC</strong> mostra la durata e il numero di tracce. Fai clic su <strong>Interrompi</strong> per completare il file.","manual.b1eb969490f1":"<strong>Nota sui codec:</strong> MP4 con H.264 e AAC (e HEVC o AV1) usa codec coperti da brevetti, forniti da <strong>ffmpeg</strong>, che <em>non è incluso</em>: Freally Capture lo scarica la prima volta che serve e lo verifica. Il formato senza perdite <strong>freally-video</strong> non richiede alcun download.","manual.691bff5377a8":"Registrazione e replay in profondità","manual.3c2d08430816":"Tutto ciò che sta intorno al file: registrazioni separate di ogni sorgente, un rifinitore di clip, vera trasparenza, suddivisione e marcatori sugli eventi, operazioni dopo la registrazione, un controllo di integrità e il timecode SMPTE. Tutto è disattivato finché non lo attivi, e nulla va online.","manual.537ffa2b9063":"Registrazione ISO per sorgente","manual.e57aa725fa41":"Apri <strong>Impostazioni → Uscita</strong> e trova <strong>Registrazione ISO</strong>. Attiva <strong>Registra «{name}» come file ISO a sé</strong> per ogni sorgente che vuoi pulita: ciascuna viene registrata prima della composizione, alla dimensione e alla frequenza dei fotogrammi della tela, così ogni file si allinea con il programma sulla timeline di montaggio. Ogni ospite remoto è una sorgente, quindi anche ogni ospite ha il suo file.","manual.4bce8f25ec9c":"Lascia selezionato <strong>Registra con i filtri della sorgente</strong> per l'aspetto elaborato, o deselezionalo per la sorgente grezza, e scegli per ogni registrazione il <strong>Formato ISO</strong> e l'<strong>Encoder video ISO</strong>. L'audio viene preso dopo i filtri ma prima del fader e del muto, così una scelta di mixaggio non silenzia mai un file ISO.","manual.7f29ae4e2c55":"<strong>Suggerimento:</strong> due registrazioni ISO sono sostenibili su una scheda grafica di fascia media; ognuna in più costa un ulteriore rendering e un'ulteriore codifica, e il pannello lo dice.","manual.b2aad668b8b9":"Il rifinitore di replay e clip","manual.c8af16e1cd4f":"Apri una registrazione salvata nella finestra <strong>Ritaglia</strong> dall'elenco delle registrazioni, scorrila con <strong>Indietro di un fotogramma</strong> e <strong>Avanti di un fotogramma</strong> e imposta i tuoi punti con <strong>Punto di ingresso</strong> e <strong>Punto di uscita</strong> mentre guardi.","manual.1f80dfd03a36":"Controlla il badge prima di esportare. Un <em>«Esporta senza ricodifica»</em> verde significa che il punto di ingresso cade su un keyframe (quasi istantaneo e senza perdite); il badge ambra avvisa che ci sarà una ricodifica: premi <strong>Keyframe</strong> per agganciare il punto di ingresso e ottenere un taglio senza perdite. Fai clic su <strong>Esporta clip</strong>, oppure su <strong>9:16</strong> per esportare una versione verticale.","manual.8a92b0b480f4":"Registrare con la trasparenza","manual.79bfd450e6aa":"In <strong>Impostazioni → Uscita</strong>, attiva <strong>Registra con trasparenza (alfa)</strong> per registrare il programma su uno sfondo trasparente nel formato <code>.frec</code> di Capture. La registrazione ottiene un proprio rendering trasparente, così l'anteprima e la diretta mantengono l'immagine normale. Dall'elenco delle registrazioni, esporta un <code>.mov</code> <strong>ProRes 4444</strong> o <strong>QuickTime Animation (QTRLE)</strong> per il tuo programma di montaggio; MP4 e MKV appiattiscono la trasparenza.","manual.fade0a9d0454":"<strong>Nota:</strong> la trasparenza è solo un flag nell'intestazione <code>.frec</code>, quindi questi file si riproducono ovunque si riproduca <code>.frec</code>, e i file più vecchi si aprono come opachi.","manual.33e5c9a96c5d":"Suddivisione e marcatori automatici","manual.5596d47693a3":"Nelle impostazioni di suddivisione per <code>.frec</code>, scegli di iniziare un nuovo file a un <strong>cambio scena</strong>, a un <strong>marcatore</strong> o a un <strong>passo della scaletta</strong>. Ogni parte inizia esattamente sul fotogramma di quell'evento e dura almeno un secondo, così una raffica di eventi non può produrre un mucchio di file minuscoli.","manual.7fc20a49c196":"Attiva <strong>Inserisci automaticamente marcatori di capitolo sugli eventi dello studio</strong> per segnare come capitoli i cambi di scena, i replay salvati, le riconnessioni, le raffiche di fotogrammi persi, gli allarmi e le azioni delle regole. Finiscono nei titoli dei capitoli MKV e nel file <code>.chapters.txt</code> accanto alla registrazione, insieme ai marcatori che inserisci con la tua scorciatoia.","manual.519fceb746f3":"Dopo la registrazione: la pipeline e il controllo di integrità","manual.561bb55d7a18":"Crea una <strong>Pipeline post-registrazione</strong> per ogni profilo a partire da un insieme fisso di passaggi: <strong>Verifica</strong>, <strong>Remux in MP4</strong>, <strong>Normalizza il volume</strong>, <strong>Rinomina</strong>, <strong>Sposta in cartella</strong>, <strong>Copia in cartella</strong>, <strong>Mostra nel file manager</strong> e <strong>Notifica gli script Lua</strong>. Viene eseguita in background con una coda dal vivo e si ferma al primo errore. Di proposito non esiste un passaggio «esegui un comando qualsiasi».","manual.2f93cddd1f21":"Esegui il controllo di integrità dopo una registrazione o quando vuoi, per un semplice esito OK, avviso o errore su <strong>Contenitore</strong>, <strong>Continuità video</strong>, <strong>Continuità audio</strong>, <strong>interleaving di audio e video</strong> e <strong>Durata</strong>. I file <code>.frec</code> ricevono il controllo approfondito; gli altri file un controllo della struttura e della decodifica tramite ffmpeg.","manual.0d291aee5546":"Esportare una copia condivisibile quando ti fermi","manual.124d2a00ed27":"In <strong>Impostazioni → Uscita</strong>, con il contenitore impostato su <code>.frec</code>, seleziona <strong>Salva anche un MP4 condivisibile accanto al master</strong>. Quando una registrazione termina, un'esportazione in background scrive accanto al master senza perdite un <code>.mp4</code> che chiunque può riprodurre.","manual.a37303723389":"La copia compare nella coda post-registrazione, ha un nome che non sovrascrive mai nulla e non tocca mai il master. È disattivata finché non la attivi.","manual.7ed8656eb1ff":"Timecode SMPTE LTC","manual.3d97874c3064":"Apri <strong>Timecode SMPTE (LTC)</strong>, attiva <strong>Genera LTC su una traccia</strong> e scegli la traccia del mixer e la frequenza dei fotogrammi per alimentare registratori e videocamere esterni. Imposta <strong>Leggi LTC da</strong> su un ingresso audio per mostrare una riga di timecode nella sovrimpressione delle statistiche e per apporre marcatori di capitolo LTC. Il classico timecode audio, completamente offline, preciso a un fotogramma a 24, 25 e 30 fps.","manual.a9f690169703":"Andare in diretta","manual.8f6df4580812":"Trasmetti direttamente dal tuo computer a una piattaforma tramite RTMP o RTMPS, mai attraverso un nostro server.","manual.dba22b61cdcc":"Apri <strong>Impostazioni → Diretta</strong> e fai clic su <strong>Aggiungi destinazione</strong>. Scegli <strong>Twitch</strong>, <strong>YouTube</strong>, <strong>Kick</strong>, <strong>Facebook</strong>, <strong>Trovo</strong> o <strong>RTMP personalizzato</strong>.","manual.2192731aac47":"Incolla la tua <strong>chiave di trasmissione</strong> (conservata sul tuo computer e mostrata mascherata) e imposta bitrate ed encoder per quel servizio.","manual.040014e94f16":"Fai clic su <strong>Vai in diretta</strong> in <strong>Controlli</strong>. La spia <strong>In diretta</strong> si accende e il pannello delle statistiche mostra il bitrate, i fotogrammi persi e lo stato della trasmissione.","manual.0cd441959cb4":"Se la connessione cade, Freally Capture <strong>si riconnette da solo</strong>, e la registrazione locale continua qualunque cosa faccia la diretta. Imposta un <strong>ritardo della trasmissione</strong> se ti serve.","manual.dc8ebcea4893":"Fai clic su <strong>Termina diretta</strong> per fermarti.","manual.973adc03e43c":"Sicurezza in onda","manual.53fa9293a65e":"Non perdere lo show: prima, durante e dopo.","manual.de8792b14216":"Prima: la verifica pre-diretta","manual.ed9a4b7bfaf5":"Fare clic su <strong>Vai in diretta</strong> esegue prima una lista di controllo: le destinazioni hanno le chiavi, è stato trovato un encoder utilizzabile, ogni sorgente è in buono stato e c'è abbastanza spazio su disco per la registrazione, ognuno verde o rosso con una correzione in un clic, più promemoria sui livelli del microfono e dell'audio del desktop e sul buffer di replay, che non bloccano mai uno show di solo schermo. Un'impostazione può <strong>trattenere Vai in diretta finché ogni controllo bloccante non è verde</strong>; altrimenti c'è «Vai in diretta comunque».","manual.9b63c5c64ba1":"Durante: allarmi, stato e failover","manual.9c386b745073":"Gli <strong>allarmi di sicurezza</strong> vigilano mentre sei in diretta o stai registrando: audio del programma silenzioso, saturazione prolungata, un'immagine nera o bloccata e una <em>previsione</em> di disco quasi pieno («circa 22 minuti rimasti al bitrate attuale»). Compaiono come un banner che puoi chiudere, e i lettori di schermo li annunciano: mai una finestra di dialogo che interrompe lo show.","manual.b7c8c66a5330":"Il <strong>pannello sullo stato delle sorgenti</strong> (palette dei comandi → «Stato delle sorgenti…») elenca per ogni sorgente lo stato, la frequenza dei fotogrammi, l'età dell'ultimo fotogramma, i fotogrammi persi e i riavvii, con <strong>Riavvia</strong> e <strong>Proprietà</strong> per ciascuna.","manual.92bd60ef963b":"Se l'encoder hardware si guasta nel mezzo di una diretta o di una registrazione (un reset del driver, la scheda grafica sotto sforzo), il <strong>failover dell'encoder</strong> passa a un altro encoder hardware o a x264. La diretta si riconnette e resta attiva, la registrazione continua in un nuovo file e un messaggio dice esattamente cosa è successo. I problemi di rete non causano mai un cambio.","manual.50a02fe4fe7b":"Il <strong>pulsante antipanico</strong> (una scorciatoia globale a tua scelta) porta il programma (e la tela verticale e gli eventuali proiettori) su una schermata di privacy, ferma ogni cattura e silenzia tutto l'audio, microfono compreso, mentre la diretta e la registrazione restano collegate. Per tornare serve una conferma deliberata in due passaggi. Imposta il colore o l'immagine della schermata accanto alla scorciatoia in <strong>Impostazioni → Scorciatoie</strong>.","manual.a73a2857361e":"Dopo: registrazioni sicure e un'uscita ordinata","manual.bf07b060e7e7":"Le registrazioni MP4 e MOV vengono scritte in <strong>frammenti</strong>, così un crash o un'interruzione di corrente lasciano comunque un file riproducibile (MKV e <code>.frec</code> lo erano già). Se una sessione termina nel mezzo di una registrazione, all'avvio successivo viene proposta una <strong>riparazione</strong> in un clic in una copia <code>(repaired)</code>; l'originale non viene mai toccato.","manual.da5eeb31c1b8":"Uscire mentre sei in diretta, stai registrando o hai il replay armato mostra cosa succederà, poi chiude tutto <strong>in ordine</strong>: termina la diretta, completa la registrazione, salva il buffer di replay, salva il tuo lavoro.","manual.26b3f2c32e05":"I <strong>nomi dei file di registrazione</strong> seguono un modello (<strong>Impostazioni → Uscita</strong>) composto da token (<code>{prefix}</code> <code>{date}</code> <code>{time}</code> <code>{scene}</code> <code>{profile}</code> <code>{canvas}</code> <code>{marker-count}</code> <code>{counter}</code>) per registrazioni, replay e fermi immagine, con cartelle proprie per replay e fermi immagine.","manual.27c3f23547ac":"<strong>Esporta diagnostica</strong> salva in un file sul tuo computer un pacchetto di dettagli tecnici, costruito da un elenco di elementi consentiti rigoroso, così chiavi di trasmissione, password, percorsi e nomi dei file non vi compaiono mai. Puoi leggere prima cosa contiene; resta dove lo salvi e non viene mai inviato da nessuna parte.","manual.5199babf9b90":"Sorgenti e dispositivi","manual.306121fdda68":"Tutto ciò che sta tra l'obiettivo e la tela: segnali di prova, calibrazione della sincronia, testo da file, timer, la mappa dei tasti, il mixer in profondità e veri controlli dei dispositivi.","manual.5eacf1ee941f":"Segnali di prova e calibrazione della sincronia A/V","manual.920b7abd63cc":"Aggiungi una sorgente <strong>Segnale di prova</strong> (<strong>Sorgenti → + → Segnale di prova</strong>): barre colore, una griglia di calibrazione, uno sweep di movimento, un tono di riferimento a 1 kHz a −20 dBFS oppure un <strong>lampo e bip</strong> combinato per la sincronia audio-video, con immagine e suono generati da un unico orologio. Verifica un proiettore, un encoder o una destinazione della diretta senza alcuna videocamera collegata.","manual.788073298328":"Apri il banco di <strong>calibrazione della sincronia A/V</strong> (palette dei comandi → «Calibrazione della sincronia A/V…»). Scegli la videocamera e il microfono da allineare, punta la videocamera sul programma che lampeggia (la finestra di dialogo può aprire un proiettore a schermo intero apposta) e lascia misurare per circa dodici secondi. Trova il lampo e il bip su più cicli e propone di applicare lo scarto misurato al microfono; il cursore manuale resta come ripiego. La misura passa attraverso lo schermo e gli altoparlanti, quindi i loro piccoli ritardi ne fanno parte, e un fallimento dice <em>perché</em>.","manual.825c83c405fb":"Timer, orologi e testo da file","manual.85622b429b51":"Una sorgente <strong>Timer</strong> mostra un orologio (con un formato a tua scelta e uno scarto UTC fisso facoltativo), un <strong>Conto alla rovescia</strong> (per una durata, o fino al prossimo orario del giorno; allo zero può lampeggiare o cambiare scena), un <strong>Cronometro</strong> oppure il <strong>tempo trascorso da quando sei andato in diretta o hai iniziato a registrare</strong>. Avvialo, mettilo in pausa e azzeralo dalle sue <strong>Proprietà</strong>, oppure assegna le due scorciatoie globali che comandano <em>tutti</em> i timer insieme (<strong>Impostazioni → Scorciatoie</strong>).","manual.fcd4f802968f":"Una sorgente <strong>Testo</strong> può <strong>leggere da un file monitorato</strong> (<strong>Proprietà → Leggi da file</strong>): un intero file <code>.txt</code>, una cella CSV (per nome o numero di colonna) o un valore JSON (un puntatore come <code>/teams/0/score</code>). Le modifiche compaiono entro mezzo secondo. Tabelloni e sottopancia senza alcun servizio dietro.","manual.1d106549f0ce":"La mappa dei tasti e la console del mixer","manual.5d6ad89f147c":"La <strong>Mappa dei tasti</strong> (palette dei comandi → «Mappa dei tasti…») elenca <em>ogni</em> assegnazione (azioni globali e il push-to-talk e push-to-mute di ogni sorgente), con ricerca e filtri, e segnala i conflitti onestamente: la stessa scorciatoia scritta in due modi viene mostrata come condivisa, e un tasto rifiutato dal sistema (perché è di un'altra app) lo dice. <strong>Esporta promemoria</strong> scrive un riferimento in Markdown nella cartella Download.","manual.e32e382b9753":"Ogni canale del mixer ha il <strong>Pan</strong> (bilanciamento stereo; al centro equivale esattamente a nessun pan, e un doppio clic lo azzera), il <strong>solo PFL</strong> (il monitor sente solo i canali in solo; il mix del programma non cambia mai) e un downmix <strong>mono</strong>. Pan e mono si trovano nel menu «⋯» del canale; il solo è sul canale stesso.","manual.5dbd70dfc92d":"Dispositivi in profondità: deinterlacciamento e controlli della videocamera","manual.f8e60899a881":"Le <strong>Proprietà</strong> di un dispositivo di acquisizione video offrono il <strong>Deinterlacciamento</strong> per i segnali interlacciati, come le schede di acquisizione collegate a videocamere e console più vecchie: discard, bob, linear, blend o motion-adaptive, con l'ordine dei campi. Funziona allo stesso modo su ogni sistema; cambiarlo riavvia il dispositivo.","manual.34192e6d30fd":"I <strong>Controlli camera</strong> (esposizione, bilanciamento del bianco, messa a fuoco, zoom, guadagno e altro) compaiono nelle stesse <strong>Proprietà</strong> mentre la videocamera è in funzione. Windows e Linux usano i controlli UVC standard; macOS mostra ciò che il sistema riporta, che spesso è nulla, e il pannello lo dice invece di mostrare cursori che non fanno niente. Ogni regolazione viene salvata in un <strong>profilo per quella videocamera</strong>, riapplicato quando viene ricollegata o l'app si riavvia; <strong>Reimposta profilo</strong> ripristina i valori predefiniti.","manual.f77f10d8c967":"Automazione e controllo","manual.726216fb4de1":"Lascia che lo studio si guidi da solo con regole, macro e controller hardware, ognuno limitato a un unico elenco fisso di comandi dello studio, così nessuna automazione può indicare un file, avviare un programma o raggiungere internet.","manual.193521bd4921":"Regole, macro e variabili","manual.e8ee7ccab125":"Apri <strong>Strumenti → Regole di automazione e macro…</strong> e aggiungi una regola. Scegli uno dei nove attivatori (un cambio di scena, l'avvio o l'arresto della diretta, l'avvio o l'arresto della registrazione, un errore di una sorgente, un livello audio che supera una soglia, il sistema che diventa inattivo, una finestra che prende il focus, un orario del giorno o la modifica di un file monitorato), aggiungi condizioni (il valore di una variabile, in diretta, in registrazione) e scegli un'azione dello studio. Ogni regola nasce <strong>disattivata</strong>: attivala per armarla.","manual.5deaa7ba718f":"Crea una macro come elenco di passaggi con un nome (esegui un'azione, attendi, imposta una variabile), con un numero di ripetizioni e una scorciatoia globale facoltativa. Eseguila dall'app, da una scorciatoia, da una regola o dall'API di controllo remoto.","manual.30ee5b1326f2":"Imposta una <strong>variabile</strong> dello studio in una macro e usala come <code>{{name}}</code> all'interno di qualsiasi sorgente Testo: il testo cambia nel momento in cui la macro imposta il valore.","manual.5eb10fc04538":"Controller: MIDI, OSC e il pannello touch","manual.ba0c838f1688":"Apri <strong>Strumenti → Controllo MIDI…</strong> e associa un pad, una manopola o un fader a un'azione, una macro, un cambio di scena, un fader del mixer o un muto, con luci e fader motorizzati che seguono lo stato reale dello studio. Nessuna porta MIDI si apre finché non ne scegli una.","manual.cc993cb0d974":"Attiva <strong>Ascolta OSC</strong> per consentire a controller in stile TouchOSC e a mixer luci di inviare indirizzi come <code>/scene/switch</code>, <code>/record/start</code>, <code>/macro/run</code> e <code>/mixer/vol</code>. È disattivato per impostazione predefinita e ascolta solo su questo computer, a meno che tu non consenta la tua rete. OSC non ha una password propria.","manual.134e5f4269f9":"Apri <strong>Strumenti → Pannello LAN e tally…</strong> per servire una pagina di controllo (pulsanti delle scene con tally dal vivo, fader del mixer e tasti azione) a qualsiasi telefono tramite un codice QR. Ogni richiesta richiede la password, e ascolta solo su questo computer a meno che tu non consenta la tua rete. La pagina del tally si mostra a tutto schermo in rosso o verde; aggiungi <code>?scene=NAME</code> per seguire una sola scena.","manual.fc4cd96b860d":"Combinazioni e livelli di scorciatoie","manual.ec4a9a334753":"In un campo scorciatoia, assegna una scorciatoia semplice (Ctrl+Shift+M) o una combinazione in due tempi (Ctrl+K, poi 3): il secondo tasto viene occupato solo mentre la combinazione è in attesa. Assegna a una scorciatoia un <strong>Livello</strong> perché funzioni solo mentre quel livello è attivo; i livelli restano impostati finché non li cambi.","manual.70ad05980925":"Videocamere e la scaletta dello show","manual.24b33b058b99":"Apri <strong>Strumenti → Telecamere PTZ…</strong>, aggiungi una videocamera tramite il suo indirizzo VISCA over IP, memorizza preimpostazioni con nome di pan, tilt e zoom e collega una preimpostazione a una scena, così passare a quella scena richiama l'inquadratura. Il PTZ resta sulla tua rete, e una videocamera esiste solo perché hai digitato il suo indirizzo: nulla viene cercato.","manual.c9d86b995c5a":"Apri <strong>Strumenti → Mostra scaletta…</strong> ed elenca i passaggi (una scena, quanto dura e azioni facoltative), avanzando a mano o automaticamente, con un «prossimo» dal vivo e il tempo rimanente. Una scaletta cambia scena nel modo ordinario, annullabile, e non modifica mai la tua raccolta di scene.","manual.5c94bed2d737":"<strong>Nota:</strong> ogni regola, macro, associazione MIDI o OSC, pulsante del pannello e passo della scaletta passa per lo stesso elenco fisso di comandi dell'API di controllo remoto, così nessun controller può fare ciò che i pulsanti dell'app stessa non possono fare. Ogni listener di rete è disattivato per impostazione predefinita e resta su questo computer a meno che tu non consenta la tua rete, e le impostazioni di OSC e del pannello ti avvisano che il traffico di rete non è cifrato prima che la porta si apra.","manual.1f3fd1c7ddc9":"Il multistream","manual.dcac0a03a29b":"Trasmetti su più piattaforme contemporaneamente, direttamente dal tuo computer, senza servizi di inoltro nel mezzo.","manual.42d9628818da":"Aggiungi due o più destinazioni in <strong>Impostazioni → Diretta</strong> e attivale una per una.","manual.4144fe0d9694":"Assegna a una piattaforma impostazioni dell'encoder proprie se le serve un bitrate diverso.","manual.cb21d6bb96be":"Fai clic su <strong>Vai in diretta</strong>: trasmetti contemporaneamente verso ogni destinazione attiva. Il pannello delle statistiche mostra lo stato e il bitrate di ogni destinazione, e il guasto di una destinazione non trascina mai giù le altre.","manual.aba9a5f55973":"Facoltativamente registra nello stesso momento una copia locale a tracce separate, e salva i replay con la scorciatoia del replay mentre trasmetti.","manual.af9343c245a7":"<strong>Gratuito oggi:</strong> ogni funzionalità (multistream, SRT e WHIP, ogni filtro, lo scripting, il replay, i pacchetti di transizioni e l'API di controllo remoto) oggi è gratuita, per tutti. Le versioni future potrebbero essere vendute.","manual.c08320c45003":"Affidabilità e analisi della diretta","manual.532ab322d03c":"Prova, misura e spiega il tuo show. Tutto ciò che trovi qui è disattivato o neutro per impostazione predefinita, e nulla va online.","manual.80390ae1a9d7":"Il simulatore di rete","manual.7e620ced841e":"In <strong>Impostazioni → Diretta</strong>, apri il <strong>Simulatore di rete (prove)</strong> e scegli un <strong>Profilo</strong>: <strong>Wi-Fi da hotel</strong>, <strong>Hotspot mobile</strong> oppure <strong>Personalizzato</strong> con valori tuoi di <strong>Larghezza di banda</strong>, <strong>Latenza</strong>, <strong>Jitter</strong> e orari programmati di <strong>Interruzione</strong>. Agisce solo sull'uscita locale di una prova, così puoi esercitarti con le riconnessioni, il multistream e le scelte di bitrate; non può mai rallentare una trasmissione reale.","manual.b22d8c51e0bd":"Modalità prova","manual.083772633b86":"Premi il pulsante viola <strong>Prova generale</strong> per eseguire l'intera pipeline (compositore, encoder, muxer e la vera logica di riconnessione) verso un sostituto locale, <strong>senza che nulla lasci il computer</strong>. Un badge <strong>PROVA</strong> contrassegna ogni controllo dal vivo, e le tue chiavi di trasmissione non vengono nemmeno lette, così puoi fare le prove prima di averle. Puoi anche registrare la prova.","manual.184d64047c4c":"<strong>Suggerimento:</strong> abbina una prova al simulatore di rete per esercitarti a riconnetterti su una connessione debole e instabile ben prima del giorno della diretta.","manual.d2381a584d24":"La timeline dei fotogrammi persi","manual.a6a72c5410a8":"La <strong>Timeline della sessione</strong> registra l'intera sessione (tempo di rendering, coda dell'encoder, bitrate e fotogrammi persi di ogni destinazione, riconnessioni, cambi di scena, marcatori e allarmi) su un unico grafico zoomabile. Dove il pannello delle statistiche mostra l'<em>adesso</em>, la timeline risponde a posteriori alla domanda «cosa è successo al minuto 43?».","manual.6e9fee1e85fa":"Il report della sessione e il benchmark degli encoder","manual.9dd812cbf648":"Attiva <strong>Scrivi un report della sessione (HTML + Markdown) accanto alla registrazione</strong> in <strong>Impostazioni → Diretta</strong> per avere un riepilogo locale alla fine della sessione: tempo di attività, bitrate medio e di picco per destinazione, il tempo trascorso offline, le riconnessioni, i marcatori, gli allarmi e la posizione della registrazione. Resta sul tuo computer ed è disattivato per impostazione predefinita.","manual.a9e574b7bd8d":"Usa <strong>Esegui benchmark encoder…</strong> per misurare brevi codifiche con ogni encoder, preimpostazione e risoluzione disponibili sul tuo computer (circa un minuto, completamente offline), poi scegli <strong>Applica alle impostazioni di registrazione</strong> dal risultato. Gli errori vengono elencati, non nascosti, e il benchmark si rifiuta di partire mentre sei in diretta o stai registrando.","manual.fae310275ed2":"Sorgenti solo nella diretta o solo nella registrazione","manual.191da176dd0d":"Nella riga di una sorgente, usa <strong>Mostra nello stream</strong> / <strong>Nascondi nello stream</strong> e <strong>Mostra nella registrazione</strong> / <strong>Nascondi nella registrazione</strong> per tenere avvisi e chat nella diretta mentre la registrazione resta pulita, da un'unica tela. Il pulsante principale a forma di occhio controlla ancora tutto, e l'anteprima, i proiettori e la multiview mostrano sempre l'intero programma.","manual.46bad2cb618f":"Videocamera virtuale","manual.69ebe5277092":"Usa il tuo programma come webcam in qualsiasi app di videochiamata. <strong>Solo Windows nella 1.2.1.</strong>","manual.ba2b6aa952f7":"Fai clic su <strong>Avvia videocamera virtuale</strong> in <strong>Controlli</strong>. Freally Capture aggiunge una videocamera di sistema chiamata <strong>«Freally Capture Virtual Camera»</strong>.","manual.cb3cb4585f19":"In Zoom, Meet, Discord o Teams, scegli quella videocamera nelle impostazioni video: il tuo programma diventa la webcam.","manual.83db59f4a370":"Fai clic su <strong>Interrompi videocamera virtuale</strong> per rimuoverla.","manual.91c51d55639b":"<strong>Per sistema:</strong> su <strong>Windows</strong> la videocamera viene registrata per il tuo utente, senza diritti di amministratore, e viene rimossa quando la interrompi. <strong>Non ha ancora la firma del codice</strong>, quindi Windows potrebbe mostrare un avviso e un'app di videochiamata con protezioni rafforzate potrebbe rifiutarla; resta ancora da fare una prova completa all'interno di una vera chiamata. Le videocamere per <strong>macOS</strong> e <strong>Linux</strong> sono componenti separati che <em>non sono in questa versione</em>. Freally Capture non installa mai un componente di sistema senza chiedere, su nessun sistema.","manual.98839b8e6880":"Sorgente browser","manual.3ba821584b20":"Inserisci una pagina web dal vivo (una sovrimpressione di avvisi, un tabellone, un widget della chat) direttamente in una scena.","manual.895f07f428cd":"In <strong>Sorgenti</strong>, fai clic su <strong>+</strong> e scegli <strong>Browser</strong>.","manual.868ee19e975e":"Incolla un indirizzo <strong>http://</strong> o <strong>https://</strong> e imposta la dimensione e la frequenza dei fotogrammi con cui renderlo.","manual.292e94b0a782":"La prima volta, Freally Capture propone di installare il componente <strong>Runtime del browser</strong>. Viene scaricato quando lo richiedi e verificato tramite il suo hash (mai incluso nell'app), e puoi rimuoverlo di nuovo da <strong>Strumenti → Componenti</strong>.","manual.cd6d7fbd46ee":"<strong>Si caricano solo http e https.</strong> La regola copre ogni cambio di pagina, non solo l'indirizzo che digiti: se una pagina prova a spostarsi su <code>file://</code>, <code>javascript:</code> o <code>data:</code> (tramite un reindirizzamento, uno script, un pop-up o un frame), lo spostamento viene <strong>annullato</strong>, così una pagina non può leggere i tuoi file. Su Windows la pagina gira nella sandbox di Chromium. L'ambiente di esecuzione <strong>non ha ancora la firma del codice</strong>. Il suono della pagina non viene ancora catturato: questa versione gestisce solo l'immagine.","manual.9c0c8f127dd9":"Cattura dei giochi","manual.2c08692420b8":"Cattura un gioco a schermo intero esclusivo che la normale cattura finestra non riesce a vedere. <strong>Solo Windows.</strong>","manual.9d162e3861e9":"In <strong>Sorgenti</strong>, fai clic su <strong>+</strong> e scegli <strong>Cattura gioco</strong>. <strong>Leggi prima l'avviso</strong>: spiega il rischio con parole semplici.","manual.4264b41a7732":"Accetta il rischio <em>per quel singolo gioco</em>, poi scegli il gioco in esecuzione dall'elenco.","manual.ab3e826e90f1":"Freally Capture carica un piccolo hook in quel gioco e ne preleva i fotogrammi alla frequenza propria del gioco.","manual.082fd06e18f9":"<strong>Leggi qui prima di usarla.</strong> La cattura dei giochi funziona <strong>caricando una DLL nel gioco</strong>. I software anti-cheat e antivirus potrebbero considerarla una manomissione, e può far <strong>bannare</strong> un account. Nulla viene mai caricato automaticamente: dai il consenso <strong>per un gioco alla volta</strong>, e quel consenso non può mai essere usato per un altro gioco, né viaggia mai all'interno di una raccolta di scene condivisa. Se un gioco rifiuta l'hook, Freally Capture ripiega sulla normale <strong>Cattura finestra</strong> con un messaggio invece di fallire. Anche i giochi HDR e Direct3D 12 usano la Cattura finestra. Su macOS e Linux questa sorgente non viene offerta.","manual.43fae75af922":"Buffer di replay","manual.40bc664c1c0b":"Tieni in memoria gli ultimi momenti, così una scorciatoia salva ciò che è appena successo.","manual.7a69241c10c2":"Fai clic su <strong>Avvia buffer di replay</strong> in <strong>Controlli</strong>. Freally Capture conserva gli ultimi secondi in un buffer di dimensione fissa.","manual.684aecea2ba0":"Assegna una scorciatoia globale <strong>Salva replay</strong> in <strong>Impostazioni</strong>.","manual.66c44777e965":"Premila per salvare gli ultimi secondi in un file, senza interrompere la diretta o la registrazione principale. Un messaggio «Replay salvato» lo conferma.","manual.4b598d5daf11":"Gobbo elettronico","manual.b7fc474ded62":"Un copione che scorre fluido per chi sta davanti alla videocamera: in un pannello dell'app, in un proiettore a schermo intero che si può specchiare e nel pannello touch della LAN, tutto contemporaneamente.","manual.f1c548f77750":"Apri il gobbo elettronico da <strong>Strumenti</strong>, digita o incolla il copione e imposta velocità e font. Regola il ritmo in <strong>caratteri al secondo</strong>, oppure passa ai <strong>BPM</strong> (50–250 battiti al minuto) per leggere testi di canzoni a tempo di musica; entrambe le modifiche reimpostano il ritmo di uno scorrimento in corso.","manual.3a86eb91938d":"<strong>Segni di pausa:</strong> digita <code> -- </code> per una breve pausa o <code> --N </code> per una sosta di N secondi e diventa un unico segno: il cursore lo scavalca, un solo Delete o Backspace lo rimuove, e copia e incolla lo mantengono intero.","manual.dc7539148aed":"<strong>Avvia conto alla rovescia:</strong> arma un'introduzione facoltativa 3-2-1, mostrata sia nell'anteprima dell'operatore sia sul proiettore, così chi legge ha un attimo prima che il testo si muova.","manual.f5113c573ac4":"<strong>Apri il proiettore</strong> per chi legge (la modalità specchio lo capovolge per il vetro beam splitter). Aprirlo chiude la finestra dell'operatore, così puoi gestire la diretta dalla finestra principale mentre l'altra persona legge; con un conto alla rovescia armato, il proiettore torna all'inizio, conta alla rovescia e parte. Riproduci, metti in pausa, ferma, riavvolgi, manda avanti e ricomincia dai controlli sullo schermo, da una scorciatoia, da MIDI, da OSC o dal pannello LAN: ogni controllo resta sincronizzato.","manual.5298a60b0152":"<strong>Leggi ad alta voce</strong> fa ascoltare un'anteprima del copione con la sintesi vocale del tuo sistema: le voci integrate di Windows, quelle di macOS e, su Linux, <code>spd-say</code> o <code>espeak-ng</code> dove sono installati. Non è incluso alcun motore di sintesi vocale.","manual.5de1b5efa245":"Il <strong>completamento automatico</strong> suggerisce parole e frasi in grigio chiaro mentre scrivi; premi Tab per accettare. Ognuna delle 18 lingue ha il proprio dizionario sul tuo computer, caricato solo per la lingua in cui stai scrivendo.","manual.7fb5d22a1670":"Controllo remoto","manual.b2ba73efdcec":"Comanda lo studio da uno Stream Deck o da un controller in stile Companion: disattivato per impostazione predefinita, protetto da password, sul tuo computer.","manual.6396674fcd28":"Apri <strong>Impostazioni → Controllo remoto</strong>, attiva l'<strong>API WebSocket</strong> (disattivata per impostazione predefinita) e imposta una <strong>Password</strong>.","manual.56e0d6d295bb":"Ascolta su <code>127.0.0.1</code>, cioè solo su questo computer, a meno che tu non consenta esplicitamente la tua rete.","manual.344e52e3eba1":"Punta un client Companion o Stream Deck all'indirizzo mostrato. Cambia scena, esegui transizioni, silenzia e riattiva l'audio, avvia e ferma la registrazione e salva replay dai pulsanti hardware.","manual.6664edd9ad4c":"Ospiti remoti e produzione dello show","manual.75ce17238f9b":"Trasforma una sessione con ospiti remoti in uno show prodotto: fino a otto ospiti, disegno sul programma dal vivo, una sala d'attesa, segnali privati, la connessione di ogni ospite a colpo d'occhio e una griglia automatica. Tutto ciò che trovi qui è disattivato o non assegnato per impostazione predefinita, e nulla si collega finché non inviti qualcuno.","manual.02d9e34002c8":"Sessioni con più ospiti","manual.5a6c2ec7640d":"Avvia una sessione con ospiti remoti e condividi il link di invito o il suo codice QR: <strong>tu più un massimo di otto ospiti</strong>, una galleria da uno a nove. Ogni ospite è un riquadro con i propri controlli di silenziamento, qualità della connessione, canale dei segnali e messa in onda in un clic.","manual.34a323a45540":"Un ospite apre il link in un browser web (non c'è nulla da installare) e tocca <strong>Partecipa</strong> per inviare la propria videocamera e il proprio microfono. Un ospite che ha Freally Capture può invece aprire lo stesso invito nell'app. Un invito scade dopo il tempo che scegli.","manual.4e31042e4a6f":"<strong>Nota:</strong> immagini e suono viaggiano direttamente tra te e ciascun ospite, peer-to-peer e cifrati durante il trasferimento; solo la negoziazione della connessione passa da un servizio di segnalazione pubblico. Le sessioni sono testate con quattro ospiti; oltre dipende dalla tua banda e dal tuo processore.","manual.33ff43cd0616":"Telestrator: disegnare sul programma dal vivo","manual.d29f651d6eb9":"Apri il <strong>Telestrator</strong> e scegli uno strumento (<strong>Penna</strong>, <strong>Evidenziatore</strong>, <strong>Freccia</strong> o <strong>Ellisse</strong>), poi disegna direttamente sul programma. I tuoi segni fanno parte dell'immagine nel momento in cui li disegni, quindi compaiono nella registrazione e nella diretta, non solo nella tua anteprima.","manual.9aa7fc0273fb":"Lascia che i segni svaniscano in <strong>Dissolvenza</strong> dopo un po', oppure passa alla <strong>Modalità lavagna</strong> per <strong>Mantenerli</strong> finché non li cancelli. Il disegno segue la pressione di una tavoletta, e <strong>Cancella segni</strong> può essere assegnato a una scorciatoia (non assegnato per impostazione predefinita).","manual.fc81cd8d37ae":"La sala d'attesa","manual.c87beb96ec64":"Attiva la <strong>Sala d'attesa</strong> e i nuovi ospiti aspettano fuori onda mentre controlli la loro videocamera e il loro microfono nell'<strong>Anteprima sala d'attesa</strong>. Quando sono pronti, fai clic su <strong>Manda in onda</strong>. L'ospite vede un banner «sei nella sala d'attesa», nell'app o nella pagina web.","manual.1d47c8224f50":"Segnali e comunicazione","manual.569d461035c1":"Invia a un ospite un <strong>Segnale</strong> privato (con preimpostazioni come <strong>30 secondi</strong>, <strong>Concludi</strong>, <strong>Tocca a te tra poco</strong> e <strong>Parla più forte</strong>) sul canale peer-to-peer già esistente della sessione. L'ospite lo vede con un conto alla rovescia dal vivo, mai nel programma.","manual.c66c9d5359bf":"Il pannello sulla qualità della connessione","manual.4541cc1ee0f5":"Osserva dal vivo la connessione di ogni ospite (tempo di andata e ritorno, perdita di pacchetti, la risoluzione e la frequenza dei fotogrammi che ricevi, e il jitter) con un badge verde, ambra o rosso e un piccolo grafico storico, così una connessione che si indebolisce si vede prima che i tuoi spettatori se ne accorgano.","manual.bf8e764221e5":"Griglie automatiche degli ospiti","manual.ffe3c227cdfc":"Attiva la <strong>Griglia automatica</strong> per tenere gli ospiti in onda in una griglia ordinata da uno a nove che si risistema da sola quando gli ospiti entrano, escono o vengono messi in onda, oppure premi il pulsante di disposizione per farlo subito. Ogni posto pubblica il nome del suo ospite come variabile <code>{{guestN}}</code>, così una sorgente titolo diventa una targhetta che si aggiorna da sola.","manual.e8630fabd4e5":"Gestione dello studio e flusso di lavoro","manual.c8c487196725":"Rendi un intero layout trasportabile e condivisibile, conserva versioni con nome delle tue scene, personalizza il tema dell'app e metti le tue azioni preferite a un tocco di distanza: tutto sul tuo computer, senza server.","manual.f87995a7cf6c":"Pacchetti di scene e versioni","manual.074bb2bf9453":"Apri la finestra dell'area di lavoro da <strong>Collezione di scene → Gestisci collezioni di scene…</strong>: gli strumenti per pacchetti, confronto, istantanee, backup e layout dei pannelli sono tutti lì.","manual.8dce3a052a05":"Fai clic su <strong>Esporta pacchetto…</strong> per raccogliere la raccolta attuale e i suoi file (immagini, media, LUT, maschere, font) in un unico <code>.fcappack</code> trasportabile. Indirizzi web e percorsi di rete vengono elencati come <em>esterni</em> invece di essere inclusi, e i font vengono segnalati per le loro licenze.","manual.c1bba88df9c5":"Fai clic su <strong>Importa pacchetto…</strong> e scegli un <code>.fcappack</code>: arriva come nuova raccolta, trova i suoi file su questo computer e passa a quella raccolta.","manual.69e7b9f6e8ab":"Fai clic su <strong>Confronta e unisci…</strong> per confrontare la raccolta attuale con un'altra raccolta, un pacchetto o un'istantanea. Esamina scene, sorgenti, trasformazioni, filtri e visibilità aggiunti, rimossi e modificati, poi scegli esattamente quali modifiche importare. Scegliere una scena porta con sé le sorgenti che usa.","manual.862a75c84629":"Fai clic su <strong>Istantanee…</strong>, dai un nome a un punto di controllo e scegli <strong>Salva istantanea</strong>. <strong>Ripristina</strong> lo riporta in seguito: il layout attuale viene prima salvato come istantanea, così un ripristino non è mai a senso unico. Vengono conservate fino a 50 istantanee, con lo spazio su disco occupato in vista.","manual.8058b1480d14":"<strong>Suggerimento:</strong> le istantanee sono una cronologia con nome accanto al salvataggio automatico e all'annullamento. Creane una prima di una modifica rischiosa e avrai sempre un punto etichettato a cui tornare.","manual.1d55a62a5fdf":"Backup, ripristino e modalità portatile","manual.250b89a976de":"Nella finestra dell'area di lavoro, fai clic su <strong>Backup e ripristino…</strong>, poi su <strong>Esporta backup…</strong> per salvare tutto (impostazioni, profili e raccolte di scene) in un unico file <code>.fcapbackup</code>.","manual.560e7e269f11":"Su un nuovo computer, fai clic su <strong>Ripristina da backup…</strong>, seleziona cosa importare (<strong>Impostazioni</strong>, <strong>Collezioni di scene</strong>, <strong>Profili</strong>) e scegli <strong>Ripristina selezionati</strong>. Poi riavvia Freally Capture per caricare le raccolte e i profili ripristinati.","manual.5b26da4b8793":"Per eseguirlo da una chiavetta USB, metti un file chiamato <code>freally-portable.txt</code> accanto al programma: tutti i suoi dati vivranno allora nella cartella del programma invece che nel tuo profilo utente. <strong>Impostazioni → Informazioni</strong> mostra se la modalità portatile è attiva e dove si trovano i dati.","manual.a31a49d41d7d":"<strong>Nota:</strong> chiavi di trasmissione e password non vengono mai scritte in un backup: inseriscile di nuovo dopo il ripristino.","manual.5b446c4ea972":"Temi, layout e azioni rapide","manual.8eea476bde73":"Apri <strong>Impostazioni → Aspetto</strong> e scegli il tema <strong>Personalizzato</strong> per modificare la tavolozza, con <strong>avvisi di contrasto</strong> dal vivo, poi usa <strong>Esporta .fctheme…</strong> o <strong>Importa .fctheme…</strong> per condividerlo.","manual.7cc0bc3a4e74":"Nei <strong>Layout dei pannelli</strong> della finestra dell'area di lavoro, salva la disposizione attuale con un nome e fai clic su un layout salvato per passarvi.","manual.c9044c09b979":"In <strong>Impostazioni</strong>, scrivi in <strong>Cerca nelle impostazioni…</strong> per saltare a qualsiasi impostazione; un indicatore mostra quali categorie hai modificato da quando l'hai aperta.","manual.a4640858ad4d":"Scegli <strong>Strumenti → Azioni rapide…</strong> per aprire la griglia di pulsanti. Fai clic su <strong>Modifica</strong>, poi su <strong>Aggiungi pulsante</strong>, imposta l'etichetta e il colore di ogni pulsante e aggiungi delle <strong>pagine</strong>. Un pulsante può cambiare scena, eseguire una macro, suonare un pad della soundboard o eseguire un comando dello studio.","manual.74ff6472576d":"<strong>Suggerimento:</strong> i pulsanti delle azioni rapide eseguono gli stessi comandi dello studio delle scorciatoie, e la griglia è condivisa con il pannello touch della LAN: configurala una volta e ce l'hai anche sul telefono.","manual.74a883a037bc":"Impostazioni","manual.5feaf4600834":"Profili, raccolte di scene, scorciatoie e lingua. Tutto è gratuito oggi, quindi non c'è nulla da attivare. <strong>Impostazioni</strong> è un'unica finestra con categorie (Generale, Aspetto, Diretta, Uscita, Replay, Scorciatoie, Rete, Accessibilità e Informazioni) che si apre dalla <strong>barra dei menu</strong> (File, Modifica, Visualizza, Pannelli, Profilo, Collezione di scene, Strumenti e Aiuto).","manual.9f6a04e85e39":"<strong>Applica significa applica.</strong> La finestra Impostazioni modifica una copia: nulla cambia finché non fai clic su <strong>Applica</strong> o <strong>OK</strong>, e <strong>Annulla</strong> ripristina esattamente ciò che avevi, anteprima del tema compresa.","manual.3fc0968ef6f9":"<strong>Profili e raccolte di scene:</strong> tieni configurazioni separate (ad esempio «Diretta» e «Registrazione locale») e passa dall'una all'altra senza riavviare, dai menu <strong>Profilo</strong> e <strong>Collezione di scene</strong>.","manual.ce6f52861bdb":"<strong>Scorciatoie:</strong> assegna ogni azione da un elenco che non può creare conflitti: scegli una scorciatoia per un'azione e sparisce dall'elenco di ogni altra azione, così due funzionalità non condividono mai un tasto. <strong>Nessuna</strong> la libera di nuovo.","manual.be52349f05be":"<strong>Accessibilità:</strong> scegli i colori dei misuratori del mixer, compreso un set adatto ai daltonici. L'intera app funziona da tastiera, e i lettori di schermo annunciano l'inizio della diretta, la registrazione, la riconnessione e i fotogrammi persi.","manual.a79c94673558":"<strong>Lingua:</strong> scegli una delle 18 lingue; l'app cambia subito, e l'arabo si legge da destra a sinistra.","manual.59274c49ac87":"Segnalare un problema","manual.c02ed8aec89d":"Sei tu a decidere se un problema arriva allo sviluppatore, e vedi esattamente cosa verrebbe inviato.","manual.4ed327c34aeb":"Quando l'app mostra un errore causato da lei stessa, accanto compare un pulsante <strong>Segnala</strong>.","manual.95da4b53fdcc":"Dopo un crash, all'avvio successivo vengono proposti <strong>Segnala</strong> o <strong>Ignora</strong>.","manual.6207904599f4":"<strong>Segnala</strong> apre nel tuo browser la pagina di segnalazione di Freally Capture su questo sito, con i dati tecnici già compilati: puoi leggerli, ma non modificarli. Aggiungi cosa stavi facendo e, se vuoi, un indirizzo email. Nulla viene inviato a meno che tu non prema <strong>Invia</strong> su quella pagina.","manual.6acd4e789ccd":"Nulla viene mai inviato in background, e <strong>Ignora</strong> non invia proprio nulla.","manual.69bd78234ffb":"Privacy e rete","manual.42f9b04c2640":"Freally Capture non ha account né telemetria, e non esiste alcun nostro servizio cloud. Ecco esattamente cosa va online e cosa no.","manual.81fe73d241a8":"<strong>Nessun account, nessuna telemetria.</strong> L'app non ti chiede mai di accedere e non invia mai da nessuna parte le tue scene, le tue registrazioni o dati di utilizzo di alcun tipo.","manual.3735a28566e9":"<strong>La tua diretta va direttamente alla piattaforma.</strong> Viaggia dal tuo computer ai servizi che configuri: non c'è alcun nostro server di inoltro.","manual.512b8fa00684":"<strong>Le tue registrazioni restano sul tuo computer,</strong> nella cartella che scegli. Nulla viene caricato online.","manual.c299fcfa1fde":"<strong>Le tue chiavi di trasmissione restano sul tuo computer,</strong> mostrate mascherate e inviate solo al servizio verso cui trasmetti.","manual.414a08bd0219":"<strong>Gli ospiti remoti si collegano peer-to-peer.</strong> Solo la negoziazione della sessione passa da un servizio di segnalazione pubblico, e solo quando avvii una sessione.","manual.20c95c4687b3":"<strong>Una sovrimpressione della chat legge la chat pubblica</strong> del canale a cui la punti, come farebbe uno spettatore non connesso: nessun account, nessuna chiave, nessun accesso.","manual.efe87d55bed1":"<strong>Due componenti vengono scaricati solo la prima volta che ti servono:</strong> ffmpeg, per i codec richiesti dalle piattaforme, e l'ambiente di esecuzione del browser, per la sorgente browser. Ciascuno proviene dal proprio editore e viene verificato prima dell'uso.","manual.3601a272b3b0":"<strong>Un controllo degli aggiornamenti</strong> scarica un piccolo file una volta a ogni avvio, e quando scegli <strong>Controlla aggiornamenti…</strong>. Non viene inviato nulla su di te o sul tuo computer, e nulla viene installato se non dici di sì.","manual.11abc96d8e21":"<strong>Una segnalazione di problemi viene inviata solo quando premi Invia</strong> sulla pagina di segnalazione, dopo che hai letto cosa contiene (vedi <a href=\"#report\">Segnalare un problema</a>).","manual.804fa6536d40":"<strong>Niente IA.</strong> Ogni filtro (soppressione del rumore, chroma key, tone mapping) è elaborazione del segnale classica. L'app non contiene alcun modello di machine learning e non ne scarica nessuno."}; for (var k in add) mine[k] = add[k]; })(window.CAPTURE_I18N = window.CAPTURE_I18N || {});
